import React, { useState } from 'react';
import {  Save, X, Plus } from 'lucide-react';

const ProfilePage = () => {
    cons
  const [profileData, setProfileData] = useState({
    fullName: '',
    bio: '',
    github: '',
    portfolio: ''
  });

  const [skills, setSkills] = useState(['React', 'Node.js']); // Initial dynamic skills
  const [newSkill, setNewSkill] = useState('');

  const addSkill = () => {
    if (newSkill && !skills.includes(newSkill)) {
      setSkills([...skills, newSkill]);
      setNewSkill('');
    }
  };

  const removeSkill = (skillToRemove) => {
    setSkills(skills.filter(skill => skill !== skillToRemove));
  };

  return (
    <div style={{ padding: '40px', backgroundColor: '#fdfbff', minHeight: '100vh' }}>
      <div style={{ maxWidth: '850px', margin: '0 auto', backgroundColor: 'white', borderRadius: '15px', padding: '30px', boxShadow: '0 10px 25px rgba(0,0,0,0.05)' }}>
        <h2 style={{ color: '#4a3f6b', marginBottom: '20px' }}>Digital CV Settings</h2>
        
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '30px' }}>
          {/* Personal Info Section */}
          <div>
            <label style={{ fontWeight: 'bold', display: 'block', marginBottom: '8px' }}>Full Name</label>
            <input 
              style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #ddd', marginBottom: '20px' }}
              name="fullName" value={profileData.fullName} onChange={(e) => setProfileData({...profileData, fullName: e.target.value})}
            />
            
            {/* Dynamic Skills Selector */}
            <label style={{ fontWeight: 'bold', display: 'block', marginBottom: '8px' }}>Technical Skills</label>
            <div style={{ display: 'flex', gap: '10px', marginBottom: '10px' }}>
              <input 
                style={{ flex: 1, padding: '10px', borderRadius: '8px', border: '1px solid #ddd' }}
                value={newSkill} onChange={(e) => setNewSkill(e.target.value)}
                placeholder="Add skill (e.g. Python)"
              />
              <button onClick={addSkill} style={{ backgroundColor: '#4a3f6b', color: 'white', border: 'none', borderRadius: '8px', padding: '0 15px' }}>
                <Plus size={18} />
              </button>
            </div>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
              {skills.map(skill => (
                <span key={skill} style={{ backgroundColor: '#f3e8ff', color: '#7e22ce', padding: '5px 12px', borderRadius: '20px', fontSize: '13px', display: 'flex', alignItems: 'center', gap: '5px' }}>
                  {skill} <X size={14} style={{ cursor: 'pointer' }} onClick={() => removeSkill(skill)} />
                </span>
              ))}
            </div>
          </div>

          {/* Links Section */}
          <div>
            <label style={{ fontWeight: 'bold', display: 'block', marginBottom: '8px' }}>GitHub URL</label>
            <input 
              style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #ddd', marginBottom: '20px' }}
              placeholder="https://github.com/..."
            />
            <label style={{ fontWeight: 'bold', display: 'block', marginBottom: '8px' }}>Portfolio</label>
            <input 
              style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #ddd' }}
              placeholder="https://..."
            />
          </div>
        </div>
        
        <button style={{ backgroundColor: '#4a3f6b', color: 'white', padding: '12px 30px', borderRadius: '10px', border: 'none', display: 'block', margin: '30px auto', cursor: 'pointer' }}>
          <Save size={18} style={{ marginRight: '8px' }} /> Save Digital CV
        </button>
      </div>
    </div>
  );
};

export default ProfilePage;
